package com.camjewell.mtagoals;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.function.DoubleUnaryOperator;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * Estimates how much longer it'll take to reach the tracked reward goal, per room. Telekinetic,
 * Alchemist and Graveyard each have a fixed points-per-action rate the game defines, so they're
 * shown as an exact action count (Alchemist also nets out held un-deposited training gold;
 * Graveyard uses a free-inventory-capacity snapshot from room entry) - optionally followed by a
 * "(~X min)"/"(~X.Y hr)" real-world time estimate from this session's observed pace in that
 * room, since how fast a player completes each action varies by skill. Enchantment has no fixed
 * rate at all (it depends on spell level, dragonstone luck and playstyle), so it's shown as an
 * estimated time remaining from that same observed-rate mechanism instead of an action count.
 */
class EstimateOverlay extends OverlayPanel
{
	/**
	 * Telekinetic Theatre awards 2 points per maze, plus an 8-point bonus every 5th consecutive
	 * maze (18 points per 5-maze cycle) - this is that cycle's steady-state average, rather than
	 * tracking exact streak position.
	 */
	private static final double TELEKINETIC_AVG_POINTS_PER_MAZE = (5 * 2 + 8) / 5.0;

	private static final int ALCHEMIST_GOLD_PER_ALCH = 30;
	private static final int ALCHEMIST_GOLD_PER_POINT = 100;

	private final MtaGoalsPlugin plugin;
	private final MtaGoalsConfig config;

	@Inject
	EstimateOverlay(MtaGoalsPlugin plugin, MtaGoalsConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.TOP_RIGHT);
		setPriority(PRIORITY_LOW);
		panelComponent.setPreferredSize(new Dimension(250, 0));
		panelComponent.setBorder(new Rectangle(3, 3, 3, 3));
		panelComponent.setGap(new Point(0, 2));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showEstimatesOverlay())
		{
			return null;
		}

		Goal goal = plugin.getGoal();
		if (goal.getSelected().isEmpty())
		{
			return null;
		}
		if (config.onlyShowInArena() && !plugin.isInArena())
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeSmallFont());

		addRow("Estimated remaining", null, null, true);

		addActionsRow("Telekinetic", goal, PizazzRoom.TELEKINETIC, "mazes",
			remaining -> Math.ceil(remaining / TELEKINETIC_AVG_POINTS_PER_MAZE));

		addAlchemistRow(goal);
		addGraveyardRow(goal);
		addEnchantmentRow(goal);

		return super.render(graphics);
	}

	private void addActionsRow(String label, Goal goal, PizazzRoom room, String unit, DoubleUnaryOperator actionsForRemaining)
	{
		Goal.RoomProgress progress = goal.getRoomProgress(room);
		if (progress == null)
		{
			return;
		}

		int remaining = Math.max(progress.goalAmount() - progress.currentAmount(), 0);
		if (remaining <= 0)
		{
			addRow(label + ":", "Done", Color.GREEN, false);
			return;
		}

		int actions = (int) actionsForRemaining.applyAsDouble(remaining);
		addRow(label + ":", actions + " " + unit + formatTimeSuffix(room, remaining), Color.WHITE, false);
	}

	/**
	 * Nets out training gold already sitting in the inventory (alched but not yet deposited)
	 * against the gold still needed, so the item count ticks down the instant you alch something
	 * rather than only after you walk over and deposit it.
	 */
	private void addAlchemistRow(Goal goal)
	{
		Goal.RoomProgress progress = goal.getRoomProgress(PizazzRoom.ALCHEMIST);
		if (progress == null)
		{
			return;
		}

		int pointsRemaining = Math.max(progress.goalAmount() - progress.currentAmount(), 0);
		if (pointsRemaining <= 0)
		{
			addRow("Alchemist:", "Done", Color.GREEN, false);
			return;
		}

		int goldNeeded = pointsRemaining * ALCHEMIST_GOLD_PER_POINT;
		int netGoldNeeded = Math.max(goldNeeded - plugin.getAlchemistGold(), 0);
		int items = (int) Math.ceil(netGoldNeeded / (double) ALCHEMIST_GOLD_PER_ALCH);
		int effectivePointsRemaining = (int) Math.ceil(netGoldNeeded / (double) ALCHEMIST_GOLD_PER_POINT);
		String text = items + " items" + formatTimeSuffix(PizazzRoom.ALCHEMIST, effectivePointsRemaining);
		addRow("Alchemist:", text, Color.WHITE, false);
	}

	/**
	 * Uses the free-inventory-capacity snapshot the plugin took when the player entered the
	 * Creature Graveyard (rather than assuming a fixed inventory size or re-scanning the
	 * inventory live), since the inventory cycles full/empty continuously during actual play.
	 */
	private void addGraveyardRow(Goal goal)
	{
		Goal.RoomProgress progress = goal.getRoomProgress(PizazzRoom.GRAVEYARD);
		if (progress == null)
		{
			return;
		}

		int remaining = Math.max(progress.goalAmount() - progress.currentAmount(), 0);
		if (remaining <= 0)
		{
			addRow("Graveyard:", "Done", Color.GREEN, false);
			return;
		}

		int availableSlots = plugin.getGraveyardCapacity();
		int pointsPerInventory = availableSlots / config.graveyardFruit().fruitPerPoint();
		if (pointsPerInventory <= 0)
		{
			addRow("Graveyard:", "visit the room first", Color.GRAY, false);
			return;
		}

		int inventories = (int) Math.ceil(remaining / (double) pointsPerInventory);
		String text = inventories + " inventories" + formatTimeSuffix(PizazzRoom.GRAVEYARD, remaining);
		addRow("Graveyard:", text, Color.WHITE, false);
	}

	private void addEnchantmentRow(Goal goal)
	{
		Goal.RoomProgress progress = goal.getRoomProgress(PizazzRoom.ENCHANTMENT);
		if (progress == null)
		{
			return;
		}

		int remaining = Math.max(progress.goalAmount() - progress.currentAmount(), 0);
		if (remaining <= 0)
		{
			addRow("Enchantment:", "Done", Color.GREEN, false);
			return;
		}

		Double pointsPerMinute = plugin.getPointsPerMinute(PizazzRoom.ENCHANTMENT);
		if (pointsPerMinute == null)
		{
			addRow("Enchantment:", "collecting data…", Color.GRAY, false);
			return;
		}

		addRow("Enchantment:", "~" + formatMinutes(remaining / pointsPerMinute), Color.WHITE, false);
	}

	/**
	 * Optional " (~X min)"/" (~X.Y hr)" suffix for the three fixed-rate rooms, using this
	 * session's observed pace in that room. Returns "" (no placeholder) whenever the toggle is
	 * off or there isn't a rate yet, per design - the action count stands alone until there's a
	 * real value to show next to it.
	 */
	private String formatTimeSuffix(PizazzRoom room, int pointsRemaining)
	{
		if (!config.showTimeEstimates())
		{
			return "";
		}
		Double pointsPerMinute = plugin.getPointsPerMinute(room);
		if (pointsPerMinute == null)
		{
			return "";
		}
		return " (~" + formatMinutes(pointsRemaining / pointsPerMinute) + ")";
	}

	private static String formatMinutes(double minutes)
	{
		if (minutes < 60)
		{
			return Math.max(1, (int) Math.ceil(minutes)) + " min";
		}
		return String.format("%.1f hr", minutes / 60.0);
	}

	private void addRow(String left, String right, Color rightColor, boolean header)
	{
		var line = LineComponent.builder()
			.left(left)
			.leftFont(header ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeFont());
		if (right != null)
		{
			line.right(right)
				.rightFont(FontManager.getRunescapeFont())
				.rightColor(rightColor);
		}
		panelComponent.getChildren().add(line.build());
	}
}

package com.camjewell.mtagoals;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * Aggregates the currently ticked reward items into a single combined target per
 * {@link PizazzRoom}, and tracks progress toward that target given the player's
 * current point totals.
 */
class Goal
{
	private final List<RewardItem> selected = new ArrayList<>();
	private String displayName = "";
	private RewardItem representativeItem = RewardItem.NONE;
	private double overallProgress = 0.0;
	private boolean metThreshold = false;

	private final Map<PizazzRoom, RoomProgress> roomProgress = new EnumMap<>(PizazzRoom.class);

	List<RewardItem> getSelected()
	{
		return selected;
	}

	String getDisplayName()
	{
		return displayName;
	}

	RewardItem getRepresentativeItem()
	{
		return representativeItem;
	}

	double getOverallProgress()
	{
		return overallProgress;
	}

	boolean isMetThreshold()
	{
		return metThreshold;
	}

	RoomProgress getRoomProgress(PizazzRoom room)
	{
		return roomProgress.get(room);
	}

	void recalculate(MtaGoalsConfig config, int[] currentPoints)
	{
		selected.clear();
		if (config.trackBeginnerWand())
		{
			selected.add(RewardItem.BEGINNER_WAND);
		}
		if (config.trackApprenticeWand())
		{
			selected.add(RewardItem.APPRENTICE_WAND);
		}
		if (config.trackTeacherWand())
		{
			selected.add(RewardItem.TEACHER_WAND);
		}
		if (config.trackMasterWand())
		{
			selected.add(RewardItem.MASTER_WAND);
		}
		if (config.trackInfinityHat())
		{
			selected.add(RewardItem.INFINITY_HAT);
		}
		if (config.trackInfinityTop())
		{
			selected.add(RewardItem.INFINITY_TOP);
		}
		if (config.trackInfinityBottoms())
		{
			selected.add(RewardItem.INFINITY_BOTTOMS);
		}
		if (config.trackInfinityGloves())
		{
			selected.add(RewardItem.INFINITY_GLOVES);
		}
		if (config.trackInfinityBoots())
		{
			selected.add(RewardItem.INFINITY_BOOTS);
		}
		if (config.trackMagesBook())
		{
			selected.add(RewardItem.MAGES_BOOK);
		}
		if (config.trackBonesToPeaches())
		{
			selected.add(RewardItem.BONES_TO_PEACHES);
		}
		if (config.trackRunePouch())
		{
			selected.add(RewardItem.RUNE_POUCH);
		}

		if (selected.isEmpty())
		{
			displayName = "";
			representativeItem = RewardItem.NONE;
		}
		else if (selected.size() == 1)
		{
			displayName = selected.get(0).itemName();
			representativeItem = selected.get(0);
		}
		else
		{
			displayName = "Selected rewards (" + selected.size() + ")";
			representativeItem = selected.get(0);
		}

		for (PizazzRoom room : PizazzRoom.ENTRIES)
		{
			int goalAmount = 0;
			for (RewardItem item : selected)
			{
				goalAmount += item.cost(room);
			}
			roomProgress.put(room, new RoomProgress(currentPoints[room.ordinal()], goalAmount));
		}

		overallProgress = roomProgress.values().stream()
			.mapToDouble(RoomProgress::percentageToGoal)
			.average()
			.orElse(0.0);

		metThreshold = !selected.isEmpty() && roomProgress.values().stream().allMatch(RoomProgress::isMet);
	}

	static final class RoomProgress
	{
		private final int currentAmount;
		private final int goalAmount;
		private final double percentageToGoal;

		RoomProgress(int currentAmount, int goalAmount)
		{
			this.currentAmount = currentAmount;
			this.goalAmount = goalAmount;
			this.percentageToGoal = goalAmount == 0 ? 1.0 : Math.min((double) currentAmount / goalAmount, 1.0);
		}

		int currentAmount()
		{
			return currentAmount;
		}

		int goalAmount()
		{
			return goalAmount;
		}

		double percentageToGoal()
		{
			return percentageToGoal;
		}

		boolean isMet()
		{
			return currentAmount >= goalAmount;
		}
	}
}

package com.camjewell.mtagoals;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.text.DecimalFormat;
import javax.inject.Inject;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;
import net.runelite.client.util.QuantityFormatter;

class GoalOverlay extends OverlayPanel
{
	private static final DecimalFormat DECIMAL_FORMAT = new DecimalFormat("0.0");
	private static final int BORDER_SIZE = 3;
	private static final int VERTICAL_GAP = 2;
	private static final int ICON_GAP = 5;
	private static final Rectangle TOP_PANEL_BORDER = new Rectangle(2, 0, 4, 4);
	private static final Color PROGRESS_BAR_BACKGROUND_COLOR = new Color(61, 56, 49);

	private final MtaGoalsPlugin plugin;
	private final MtaGoalsConfig config;
	private final ItemManager itemManager;

	private final PanelComponent topPanel = new PanelComponent();

	private BufferedImage cachedRewardIcon;
	private RewardItem cachedRewardItem;

	@Inject
	GoalOverlay(MtaGoalsPlugin plugin, MtaGoalsConfig config, ItemManager itemManager)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;

		setPosition(OverlayPosition.TOP_RIGHT);
		setPriority(PRIORITY_MED);
		panelComponent.setPreferredSize(new Dimension(250, 0));
		panelComponent.setBorder(new Rectangle(BORDER_SIZE, BORDER_SIZE, BORDER_SIZE, BORDER_SIZE));
		panelComponent.setGap(new Point(0, VERTICAL_GAP));

		topPanel.setBorder(TOP_PANEL_BORDER);
		topPanel.setBackgroundColor(null);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Goal goal = plugin.getGoal();

		if (goal.getSelected().isEmpty())
		{
			return null;
		}
		if (config.onlyShowInArena() && !plugin.isInArena())
		{
			return null;
		}

		topPanel.getChildren().clear();
		graphics.setFont(FontManager.getRunescapeSmallFont());

		var topLine = LineComponent.builder()
			.left(goal.getDisplayName())
			.leftFont(FontManager.getRunescapeFont())
			.build();

		var bottomLine = LineComponent.builder()
			.left("Progress:")
			.leftFont(FontManager.getRunescapeFont())
			.right(DECIMAL_FORMAT.format(goal.getOverallProgress() * 100) + "%")
			.rightFont(FontManager.getRunescapeFont())
			.rightColor(goal.isMetThreshold() ? Color.GREEN : Color.WHITE)
			.build();

		var textSplit = SplitComponent.builder()
			.first(topLine)
			.second(bottomLine)
			.orientation(ComponentOrientation.VERTICAL)
			.build();

		var rewardImageComponent = new ImageComponent(getRewardImage(goal.getRepresentativeItem()));
		var topInfoSplit = SplitComponent.builder()
			.first(rewardImageComponent)
			.second(textSplit)
			.orientation(ComponentOrientation.HORIZONTAL)
			.gap(new Point(ICON_GAP, 0))
			.build();

		topPanel.getChildren().add(topInfoSplit);
		panelComponent.getChildren().add(topPanel);

		if (config.showRoomBars())
		{
			for (PizazzRoom room : PizazzRoom.ENTRIES)
			{
				addRoomBar(goal, room);
			}
		}

		if (!plugin.isReadingLivePoints())
		{
			var sourceLine = LineComponent.builder()
				.left(config.useManualPoints() ? "Manual totals" : "Waiting for lobby HUD…")
				.leftColor(Color.GRAY)
				.leftFont(FontManager.getRunescapeSmallFont())
				.build();
			panelComponent.getChildren().add(sourceLine);
		}

		return super.render(graphics);
	}

	private void addRoomBar(Goal goal, PizazzRoom room)
	{
		var data = goal.getRoomProgress(room);
		if (data == null)
		{
			return;
		}

		var progressBar = new OutlinedProgressBarComponent();
		progressBar.setForegroundColor(room.color());
		progressBar.setBackgroundColor(PROGRESS_BAR_BACKGROUND_COLOR);
		progressBar.setPercentage(data.percentageToGoal());
		progressBar.setLeftLabel(room.shortName());
		progressBar.setRightLabel(QuantityFormatter.quantityToStackSize(data.currentAmount())
			+ "/" + QuantityFormatter.quantityToStackSize(data.goalAmount()));

		// Alchemist earns training gold into the inventory before it's deposited into banked
		// points, so tint the portion of the remaining bar that depositing held gold would
		// close - a translucent version of the room's own fill color, so it reads as "this
		// much more, pending" rather than a whole new color in the palette.
		if (room == PizazzRoom.ALCHEMIST && data.goalAmount() > 0)
		{
			double pendingFraction = plugin.getAlchemistHeldPoints() / (double) data.goalAmount();
			if (pendingFraction > 0)
			{
				Color base = room.color();
				progressBar.setPendingPercentage(pendingFraction);
				progressBar.setPendingColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), 120));
			}
		}

		int remaining = Math.max(data.goalAmount() - data.currentAmount(), 0);
		String remainingText = remaining > 0 ? "(" + QuantityFormatter.quantityToStackSize(remaining) + ")" : "";

		if (config.showRoomPercentages())
		{
			String percentText = DECIMAL_FORMAT.format(data.percentageToGoal() * 100) + "%";
			progressBar.setCenterLabel(remainingText.isEmpty() ? percentText : percentText + " " + remainingText);
		}
		else if (!remainingText.isEmpty())
		{
			progressBar.setCenterLabel(remainingText);
		}

		panelComponent.getChildren().add(progressBar);
	}

	private BufferedImage getRewardImage(RewardItem rewardItem)
	{
		if (cachedRewardItem != rewardItem)
		{
			cachedRewardItem = rewardItem;
			cachedRewardIcon = itemManager.getImage(rewardItem.itemId());
		}
		return cachedRewardIcon;
	}
}

package com.camjewell.mtagoals;

/**
 * The fruit deposited in the Creature Graveyard hopper - peaches are worth twice as many
 * points per fruit as bananas (1 point per 8 peaches vs. 1 point per 16 bananas).
 */
public enum GraveyardFruit
{
	BANANAS("Bananas", 16),
	PEACHES("Peaches", 8);

	private final String displayName;
	private final int fruitPerPoint;

	GraveyardFruit(String displayName, int fruitPerPoint)
	{
		this.displayName = displayName;
		this.fruitPerPoint = fruitPerPoint;
	}

	public int fruitPerPoint()
	{
		return fruitPerPoint;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.camjewell.mtagoals;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;

import static com.camjewell.mtagoals.MtaGoalsConfig.CONFIG_GROUP;

@ConfigGroup(CONFIG_GROUP)
